function isBalanced(num) {
  // Straight from the definition: keep the digits of one parity, add them up, compare the two totals.
  const digits = [...num].map(Number);
  const total = parity => digits.filter((_, index) => index % 2 === parity).reduce((sum, d) => sum + d, 0);
  return total(0) === total(1);
}

