function generate(rand, size) {
  const n = size === 'large' ? 100 : 2 + Math.floor(rand() * 9);
  const digits = Array.from({ length: n }, () => Math.floor(rand() * 10));
  // Random digits are rarely balanced, so half of the inputs are nudged one step at a time until they are.
  if (rand() < 0.5) {
    let diff = 0;
    digits.forEach((d, i) => { diff += i % 2 === 0 ? d : -d; });
    while (diff !== 0) {
      const i = Math.floor(rand() * n), even = i % 2 === 0;
      if (diff > 0 && even && digits[i] > 0) { digits[i]--; diff--; }
      else if (diff > 0 && !even && digits[i] < 9) { digits[i]++; diff--; }
      else if (diff < 0 && even && digits[i] < 9) { digits[i]++; diff++; }
      else if (diff < 0 && !even && digits[i] > 0) { digits[i]--; diff++; }
    }
  }
  return [digits.join('')];
}
